import{_ as a,c as o,o as t,ae as r}from"./chunks/framework.CliRSA9F.js";const i="/images/planner.webp",c=JSON.parse('{"title":"Planner","description":"","frontmatter":{},"headers":[],"relativePath":"features/planner.md","filePath":"features/planner.md"}'),n={name:"features/planner.md"};function s(l,e,d,h,g,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="planner" tabindex="-1">Planner <a class="header-anchor" href="#planner" aria-label="Permalink to &quot;Planner&quot;">​</a></h1><h2 id="plan-optimize-and-produce-episodes-strategically" tabindex="-1">Plan, Optimize, and Produce Episodes Strategically <a class="header-anchor" href="#plan-optimize-and-produce-episodes-strategically" aria-label="Permalink to &quot;Plan, Optimize, and Produce Episodes Strategically&quot;">​</a></h2><p>The Planner is your episode planning hub. It combines a kanban board for managing episode ideas, a calendar view for scheduling, and an AI-powered producer for discovering new topics — all anchored by a real-time view of how well your podcast metadata aligns with your keyword strategy.</p><p><img src="'+i+'" alt="Planner Dashboard" width="600px" style="display:block;margin:0 auto;"></p><p><strong>To access</strong>: Click <strong>Command Center</strong> in the sidebar, then open the <strong>Planner</strong>.</p><h2 id="metadata-keyword-alignment" tabindex="-1"><strong>Metadata / Keyword Alignment</strong> <a class="header-anchor" href="#metadata-keyword-alignment" aria-label="Permalink to &quot;**Metadata / Keyword Alignment**&quot;">​</a></h2><p>At the top of the Planner, the Metadata/Keyword Alignment card shows how well your podcast&#39;s metadata matches your current Primary keyword strategy. This is the central place to assess and improve your podcast&#39;s SEO fitness.</p><h3 id="alignment-scores" tabindex="-1"><strong>Alignment Scores</strong> <a class="header-anchor" href="#alignment-scores" aria-label="Permalink to &quot;**Alignment Scores**&quot;">​</a></h3><p>The card displays scores for each metadata component:</p><ul><li><strong>Title</strong> — How well your podcast title incorporates your Primary keywords</li><li><strong>Author</strong> — Keyword alignment in your author/creator field</li><li><strong>Description</strong> — How effectively your description integrates target keywords</li><li><strong>Episodes</strong> — How well your planned and published episodes align with your strategy</li></ul><p>Each score is shown as a progress bar with a numeric rating, making it easy to spot which areas need improvement.</p><h3 id="get-ai-suggestions-to-improve" tabindex="-1"><strong>Get AI Suggestions to Improve</strong> <a class="header-anchor" href="#get-ai-suggestions-to-improve" aria-label="Permalink to &quot;**Get AI Suggestions to Improve**&quot;">​</a></h3><p>Click <strong>&quot;Get AI suggestions to improve&quot;</strong> to receive personalized, AI-powered recommendations for optimizing your title, author field, and description. The suggestions are tailored to your specific Primary keywords and provide concrete changes you can implement.</p><p>This feature replaces what was previously available as a standalone SEO Analysis page — now integrated directly into your planning workflow.</p><h3 id="primary-keywords-rankings" tabindex="-1"><strong>Primary Keywords Rankings</strong> <a class="header-anchor" href="#primary-keywords-rankings" aria-label="Permalink to &quot;**Primary Keywords Rankings**&quot;">​</a></h3><p>Next to the alignment scores, a table shows your current search rankings for each Primary keyword across Apple Podcasts, Spotify, Amazon Music, and YouTube Music. This gives you immediate feedback on how your optimization efforts are performing.</p><p>If your Primary keywords haven&#39;t changed in several weeks, a reminder suggests rotating your strategy to keep your SEO fresh.</p><p>Quick links let you <strong>Edit strategy</strong> (jump to Keyword Strategy) or <strong>View all tracked</strong> (jump to Keyword Tracker).</p><h2 id="board-tab" tabindex="-1"><strong>Board Tab</strong> <a class="header-anchor" href="#board-tab" aria-label="Permalink to &quot;**Board Tab**&quot;">​</a></h2><p>The Board provides a kanban-style view for managing your episode pipeline.</p><h3 id="columns" tabindex="-1"><strong>Columns</strong> <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;**Columns**&quot;">​</a></h3><ul><li><strong>Ideas</strong> — Episode concepts you&#39;re considering. Add ideas manually or import them from the AI Producer.</li><li><strong>In Progress</strong> — Episodes you&#39;re actively working on. When you move a card here, you can ask PodSEO for AI-powered title and description suggestions aligned with your keyword strategy.</li><li><strong>Published</strong> — Episodes that have been released. Published episodes can be analyzed individually for keyword alignment — unlike the previous system that only analyzed the last 4 episodes, you can now review any episode on your board.</li></ul><h3 id="working-with-cards" tabindex="-1"><strong>Working with Cards</strong> <a class="header-anchor" href="#working-with-cards" aria-label="Permalink to &quot;**Working with Cards**&quot;">​</a></h3><ul><li><strong>Add ideas</strong> using the &quot;+ Add Idea&quot; button</li><li><strong>Move cards</strong> between columns as episodes progress through your workflow</li><li><strong>Get AI suggestions</strong> for title and description when an episode is in progress</li><li><strong>Link to feed</strong> — Connect planned episodes to published feed entries</li></ul><h2 id="calendar-tab" tabindex="-1"><strong>Calendar Tab</strong> <a class="header-anchor" href="#calendar-tab" aria-label="Permalink to &quot;**Calendar Tab**&quot;">​</a></h2><p>The Calendar view shows your episodes on a timeline, helping you visualize your publishing cadence.</p><ul><li><strong>Month view</strong> — See all episodes in a traditional calendar grid</li><li><strong>Timeline view</strong> — A linear view of episode dates for planning ahead</li></ul><p>Use the Calendar to maintain a consistent publishing schedule, which is an important factor in platform algorithms and listener retention.</p><h2 id="ai-producer-tab" tabindex="-1"><strong>AI Producer Tab</strong> <a class="header-anchor" href="#ai-producer-tab" aria-label="Permalink to &quot;**AI Producer Tab**&quot;">​</a></h2><p>The AI Producer helps you discover new episode topics and content opportunities.</p><h3 id="what-it-analyzes" tabindex="-1"><strong>What It Analyzes</strong> <a class="header-anchor" href="#what-it-analyzes" aria-label="Permalink to &quot;**What It Analyzes**&quot;">​</a></h3><ul><li><strong>Trending topics</strong> — What&#39;s gaining attention in your podcast&#39;s niche right now</li><li><strong>Content gaps</strong> — Topics your competitors cover that you haven&#39;t addressed yet</li><li><strong>Keyword opportunities</strong> — Keywords with growth potential based on your strategy and rankings</li></ul><h3 id="from-ideas-to-board" tabindex="-1"><strong>From Ideas to Board</strong> <a class="header-anchor" href="#from-ideas-to-board" aria-label="Permalink to &quot;**From Ideas to Board**&quot;">​</a></h3><p>When the AI Producer suggests a topic, you can add it to your Board&#39;s Ideas column with a single click. This creates a seamless flow from discovery to planning to production.</p><h2 id="social-publishing" tabindex="-1"><strong>Social Publishing</strong> <a class="header-anchor" href="#social-publishing" aria-label="Permalink to &quot;**Social Publishing**&quot;">​</a></h2><p>The Planner&#39;s view switcher also includes a <strong>Social Publishing</strong> button. Rather than opening inside the Planner, it takes you to the dedicated Social Publishing page, where you can turn your episodes into short video reels — surface an episode&#39;s best moments, generate vertical clips, and publish them to YouTube Shorts and LinkedIn (with TikTok, Instagram, and Threads coming soon).</p><p>For a full walkthrough, see the <a href="/features/social-publishing.html">Social Publishing</a> article.</p><h2 id="the-planning-workflow" tabindex="-1"><strong>The Planning Workflow</strong> <a class="header-anchor" href="#the-planning-workflow" aria-label="Permalink to &quot;**The Planning Workflow**&quot;">​</a></h2><p>The Planner supports a complete episode planning cycle:</p><ol><li><strong>Check alignment</strong> — Review your Metadata/Keyword Alignment scores to understand your current SEO position</li><li><strong>Get suggestions</strong> — Use &quot;Get AI suggestions to improve&quot; to identify specific metadata improvements</li><li><strong>Discover topics</strong> — Use the AI Producer to find relevant new episode ideas</li><li><strong>Plan episodes</strong> — Add ideas to the Board and organize your pipeline</li><li><strong>Optimize content</strong> — As episodes move to In Progress, get AI-powered title and description recommendations</li><li><strong>Track results</strong> — After publishing, monitor how episodes perform in <a href="/features/keyword-strategy.html">Search Visibility</a></li></ol><h2 id="integration-with-other-features" tabindex="-1"><strong>Integration with Other Features</strong> <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;**Integration with Other Features**&quot;">​</a></h2><ul><li><strong><a href="/features/keyword-strategy.html">Keyword Strategy</a></strong> — Your Primary keywords drive the alignment scores and AI suggestions</li><li><strong><a href="/features/positioning.html">Positioning</a></strong> — Your strategic positioning informs the AI Producer&#39;s topic recommendations</li><li><strong><a href="/features/competitive-analysis.html">Competitive Analysis</a></strong> — Competitor data feeds into content gap analysis</li><li><strong><a href="/features/show-rankings.html">Show Rankings</a></strong> and <strong><a href="/features/keyword-tracker.html">Keyword Tracker</a></strong> — Track the impact of your optimization efforts</li></ul><h2 id="availability" tabindex="-1"><strong>Availability</strong> <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;**Availability**&quot;">​</a></h2><p>The Board and Calendar are available to all users. On the free plan, the Board can hold up to 3 active planned episodes at a time; paid plans are effectively unlimited. The AI Producer and AI-powered suggestions require a paid plan.</p><hr><h3 id="pro-tips" tabindex="-1"><strong>Pro Tips</strong> <a class="header-anchor" href="#pro-tips" aria-label="Permalink to &quot;**Pro Tips**&quot;">​</a></h3><ul><li>Review the Metadata/Keyword Alignment card every time you update your keyword strategy — it updates in real time</li><li>Use the AI Producer regularly to keep your content pipeline full of strategically relevant ideas</li><li>Don&#39;t optimize all metadata at once — make changes incrementally so you can track what&#39;s driving ranking improvements</li><li>Primary keywords are best for show-level metadata (title, description), while Secondary keywords work well for individual episode optimization</li><li>Plan in batches of 5-10 episodes aligned with your current keyword strategy, then evaluate results before adjusting</li></ul><p>The Planner brings together planning, optimization, and content discovery into a single workflow, helping you create episodes that are both valuable to your audience and optimized for discoverability.</p>',48)])])}const m=a(n,[["render",s]]);export{c as __pageData,m as default};
